vertexShader:
attribute vec4 aV; attribute vec2 aT; uniform float uTime, uH; varying float vHeat;
void main() {
  float tt = fract(uTime / aT.x + aT.y) * aT.x, life = 2.4;
  vec3 p = position + aV.xyz * tt + vec3(0., -4.9 * tt * tt, 0.);
  vec4 mv = viewMatrix * vec4(p, 1.); gl_Position = projectionMatrix * mv;
  float on = step(tt, life) * step(position.y - .2, p.y);
  gl_PointSize = on * min(aV.w * (1. - .45 * tt / life) * projectionMatrix[1][1] * uH * .5 / max(-mv.z, .5), 120.);
  vHeat = tt / life;
}

fragmentShader:
varying float vHeat;
void main() { float r = length(gl_PointCoord - .5); if (r > .5) discard;
  vec3 c = mix(vec3(2.6, 1.5, .4), vec3(1.2, .18, .02), smoothstep(.1, .8, vHeat));
  gl_FragColor = vec4(c * (1. - smoothstep(.25, .5, r)) * (1. - smoothstep(.75, 1., vHeat)), 1.);
  #include <colorspace_fragment>
}
